CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE knowledge_bases(id uuid PRIMARY KEY, name text NOT NULL, current_release uuid);
CREATE TABLE domain_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kb_id uuid NOT NULL REFERENCES knowledge_bases, payload jsonb NOT NULL, UNIQUE(kb_id,id));
CREATE TABLE source_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kb_id uuid NOT NULL REFERENCES knowledge_bases, source_key text NOT NULL, sha256 text NOT NULL, filename text NOT NULL, byte_count bigint NOT NULL, UNIQUE(kb_id,id), UNIQUE(kb_id,source_key,sha256));
CREATE TABLE source_withdrawals(kb_id uuid NOT NULL, source_version_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(kb_id,source_version_id), FOREIGN KEY(kb_id,source_version_id) REFERENCES source_versions(kb_id,id));
CREATE TABLE parse_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kb_id uuid NOT NULL, source_version_id uuid NOT NULL, parser_version text NOT NULL, UNIQUE(kb_id,id), FOREIGN KEY(kb_id,source_version_id) REFERENCES source_versions(kb_id,id));
CREATE TABLE source_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kb_id uuid NOT NULL, parse_version_id uuid NOT NULL, ordinal integer NOT NULL, text text NOT NULL, locator jsonb NOT NULL, fingerprint text NOT NULL, UNIQUE(kb_id,id), FOREIGN KEY(kb_id,parse_version_id) REFERENCES parse_versions(kb_id,id));
CREATE TABLE records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kb_id uuid NOT NULL REFERENCES knowledge_bases, kind text NOT NULL CHECK(kind IN ('object','assertion','relation','event','rule')), payload jsonb NOT NULL, status text NOT NULL CHECK(status IN ('candidate','verified','confirmed','disputed')), UNIQUE(kb_id,id));
CREATE TABLE evidence_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kb_id uuid NOT NULL, record_id uuid NOT NULL, block_id uuid NOT NULL, quote text NOT NULL, start_offset integer NOT NULL, end_offset integer NOT NULL, UNIQUE(kb_id,id), FOREIGN KEY(kb_id,record_id) REFERENCES records(kb_id,id), FOREIGN KEY(kb_id,block_id) REFERENCES source_blocks(kb_id,id));
CREATE TABLE builds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kb_id uuid NOT NULL REFERENCES knowledge_bases, record_ids uuid[] NOT NULL, ready boolean NOT NULL DEFAULT false, manifest jsonb NOT NULL DEFAULT '{}', UNIQUE(kb_id,id));
CREATE TABLE releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kb_id uuid NOT NULL, build_id uuid NOT NULL, manifest jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(kb_id,id), UNIQUE(kb_id,build_id), FOREIGN KEY(kb_id,build_id) REFERENCES builds(kb_id,id));
ALTER TABLE knowledge_bases ADD CONSTRAINT current_release_fk FOREIGN KEY(id,current_release) REFERENCES releases(kb_id,id);
CREATE FUNCTION immutable_row() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable version: create a new version' USING ERRCODE='55000'; END $$;
